-- Operational expenses and cash custody. Native receipts/payments remain the sole financial source.
CREATE TABLE treasury_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN('Cash','Bank','Wallet')),currency TEXT NOT NULL REFERENCES currencies(code),opened_on TEXT NOT NULL,allow_overdraft INTEGER NOT NULL DEFAULT 0 CHECK(allow_overdraft IN(0,1)),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE treasury_expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,number TEXT UNIQUE,incurred_on TEXT NOT NULL,category TEXT NOT NULL,supplier TEXT NOT NULL,invoice_ref TEXT NOT NULL DEFAULT '',description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),currency TEXT NOT NULL REFERENCES currencies(code),rate REAL NOT NULL CHECK(rate>0),base_amount INTEGER NOT NULL CHECK(base_amount>=0),base_currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN('Active','Voided')),void_reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE UNIQUE INDEX treasury_invoice_once ON treasury_expenses(supplier,invoice_ref,currency) WHERE invoice_ref<>'' AND status='Active';
CREATE TABLE treasury_transfers(id INTEGER PRIMARY KEY AUTOINCREMENT,from_account INTEGER NOT NULL REFERENCES treasury_accounts(id),to_account INTEGER NOT NULL REFERENCES treasury_accounts(id),date TEXT NOT NULL,sent INTEGER NOT NULL CHECK(sent>0),received INTEGER NOT NULL CHECK(received>0),note TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(from_account<>to_account));
CREATE TABLE treasury_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL REFERENCES treasury_accounts(id),date TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('Opening','Native','ExpensePayment','TransferOut','TransferIn','Reversal')),amount INTEGER NOT NULL CHECK(amount<>0),native_kind TEXT,native_id INTEGER,expense_id INTEGER REFERENCES treasury_expenses(id),transfer_id INTEGER REFERENCES treasury_transfers(id),reversal_of INTEGER UNIQUE REFERENCES treasury_entries(id),note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX treasury_entry_date ON treasury_entries(account_id,date,id);
CREATE TABLE treasury_native_links(native_kind TEXT NOT NULL CHECK(native_kind IN('sp','tp','pp','cp','ad')),native_id INTEGER NOT NULL,entry_id INTEGER NOT NULL UNIQUE REFERENCES treasury_entries(id),PRIMARY KEY(native_kind,native_id));
CREATE TABLE treasury_statements(id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL REFERENCES treasury_accounts(id),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,opening INTEGER NOT NULL,closing INTEGER NOT NULL,source_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN('Open','Closed')),created_at TEXT NOT NULL,closed_at TEXT,UNIQUE(account_id,source_hash),CHECK(starts_on<=ends_on));
CREATE TABLE treasury_statement_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,statement_id INTEGER NOT NULL REFERENCES treasury_statements(id),account_id INTEGER NOT NULL REFERENCES treasury_accounts(id),date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount<>0),reference TEXT NOT NULL,description TEXT NOT NULL,UNIQUE(account_id,reference));
CREATE TABLE treasury_matches(line_id INTEGER PRIMARY KEY REFERENCES treasury_statement_lines(id),entry_id INTEGER NOT NULL UNIQUE REFERENCES treasury_entries(id),matched_by TEXT NOT NULL,matched_at TEXT NOT NULL);
CREATE TRIGGER treasury_entries_immutable_update BEFORE UPDATE ON treasury_entries BEGIN SELECT RAISE(ABORT,'Treasury entries are immutable; use a recorded correction'); END;
CREATE TRIGGER treasury_entries_immutable_delete BEFORE DELETE ON treasury_entries BEGIN SELECT RAISE(ABORT,'Treasury entries cannot be deleted'); END;
CREATE TRIGGER treasury_accounts_identity BEFORE UPDATE ON treasury_accounts WHEN NEW.currency<>OLD.currency OR NEW.opened_on<>OLD.opened_on OR NEW.name<>OLD.name OR NEW.kind<>OLD.kind OR NEW.allow_overdraft<>OLD.allow_overdraft BEGIN SELECT RAISE(ABORT,'Account currency, opening date and identity are fixed'); END;
CREATE TRIGGER treasury_expense_identity BEFORE UPDATE ON treasury_expenses WHEN NEW.incurred_on<>OLD.incurred_on OR NEW.category<>OLD.category OR NEW.supplier<>OLD.supplier OR NEW.invoice_ref<>OLD.invoice_ref OR NEW.description<>OLD.description OR NEW.amount<>OLD.amount OR NEW.currency<>OLD.currency OR NEW.rate<>OLD.rate OR NEW.base_amount<>OLD.base_amount OR NEW.base_currency<>OLD.base_currency BEGIN SELECT RAISE(ABORT,'Recorded expense terms are fixed; void and replace'); END;
CREATE TRIGGER treasury_expense_no_delete BEFORE DELETE ON treasury_expenses BEGIN SELECT RAISE(ABORT,'Expenses must be voided, not deleted'); END;
CREATE TRIGGER treasury_lines_no_update BEFORE UPDATE ON treasury_statement_lines BEGIN SELECT RAISE(ABORT,'Statement lines are immutable'); END;
CREATE TRIGGER treasury_lines_no_delete BEFORE DELETE ON treasury_statement_lines BEGIN SELECT RAISE(ABORT,'Statement lines cannot be deleted'); END;
CREATE TRIGGER treasury_matches_closed_delete BEFORE DELETE ON treasury_matches WHEN EXISTS(SELECT 1 FROM treasury_statement_lines l JOIN treasury_statements s ON s.id=l.statement_id WHERE l.id=OLD.line_id AND s.status='Closed') BEGIN SELECT RAISE(ABORT,'A closed reconciliation cannot be changed'); END;
CREATE TRIGGER treasury_matches_no_update BEFORE UPDATE ON treasury_matches BEGIN SELECT RAISE(ABORT,'Unmatch an open statement before matching again'); END;

CREATE TRIGGER treasury_native_sp_update BEFORE UPDATE ON student_payments WHEN (NEW.p IS NOT OLD.p OR NEW.date IS NOT OLD.date OR NEW.cur IS NOT OLD.cur OR NEW.amt IS NOT OLD.amt OR NEW.rx IS NOT OLD.rx OR NEW.bamt IS NOT OLD.bamt OR NEW.bc IS NOT OLD.bc) AND EXISTS(SELECT 1 FROM treasury_entries WHERE native_kind='sp' AND native_id=OLD.id) BEGIN SELECT RAISE(ABORT,'A treasury-linked financial snapshot is immutable'); END;
CREATE TRIGGER treasury_native_sp_delete BEFORE DELETE ON student_payments WHEN EXISTS(SELECT 1 FROM treasury_entries WHERE native_kind='sp' AND native_id=OLD.id) BEGIN SELECT RAISE(ABORT,'A treasury-linked financial record cannot be deleted'); END;

