CREATE TRIGGER treasury_native_ad_update BEFORE UPDATE ON student_adjustments WHEN (NEW.s IS NOT OLD.s OR NEW.pr IS NOT OLD.pr OR NEW.kind IS NOT OLD.kind OR NEW.date IS NOT OLD.date OR NEW.cur IS NOT OLD.cur OR NEW.amt IS NOT OLD.amt OR NEW.rx IS NOT OLD.rx OR NEW.bamt IS NOT OLD.bamt OR NEW.bc IS NOT OLD.bc OR NEW.ok IS NOT OLD.ok OR NEW.oid IS NOT OLD.oid) AND EXISTS(SELECT 1 FROM treasury_entries WHERE native_kind='ad' AND native_id=OLD.id) BEGIN SELECT RAISE(ABORT,'A treasury-linked financial snapshot is immutable'); END;
CREATE TRIGGER treasury_native_ad_delete BEFORE DELETE ON student_adjustments WHEN EXISTS(SELECT 1 FROM treasury_entries WHERE native_kind='ad' AND native_id=OLD.id) BEGIN SELECT RAISE(ABORT,'A treasury-linked financial record cannot be deleted'); END;
